INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7653161, 1245707, 83313, '<td valign="top">Roful join Grog''s hunting partee. Roful use icee stare to intimedate mammoth to give up. Thag laffs at Roful. Mammoth falls on Thag. Grog laffs.</td>', 'Roful join Grog''s hunting partee. Roful use icee stare to intimedate mammoth to give up. Thag laffs at Roful. Mammoth falls on Thag. Grog laffs.', '2020-02-10 00:17:57.000000', NULL, 1),
(7653170, 1245667, 28742, '<td valign="top">Life was hard back then. Plus, I think you had to stay still for several minutes. ;-)</td>', 'Life was hard back then. Plus, I think you had to stay still for several minutes. ;-)', '2020-02-10 01:24:41.000000', NULL, 1),
(7653171, 1245658, 28742, '<td valign="top">Hey, my first TEN and top pick so far. Blue for sure. Supremely executed.</td>', 'Hey, my first TEN and top pick so far. Blue for sure. Supremely executed.', '2020-02-10 01:25:34.000000', NULL, 1),
(7653179, 1245653, 4008, '<td valign="top">Beautiful, with great detail and great distribution of tones. My eyes are drawn to the building and then to the mountains and back.</td>', 'Beautiful, with great detail and great distribution of tones. My eyes are drawn to the building and then to the mountains and back.', '2020-02-10 03:22:56.000000', NULL, 1),
(7653182, 1245402, 4008, '<td valign="top">Nice image with an old style feel to it. Good composition. I wanted to suggest that it might have been better moving the camera a bit up and to the right, but then I realized you would have lost the open part of the cloth, which adds nice detail. Just a bit ore empty space top right then? Or crop a bit of the left? It just feels a little bit unbalanced to me.</td>', 'Nice image with an old style feel to it. Good composition. I wanted to suggest that it might have been better moving the camera a bit up and to the right, but then I realized you would have lost the open part of the cloth, which adds nice detail. Just a bit ore empty space top right then? Or crop a bit of the left? It just feels a little bit unbalanced to me.', '2020-02-10 04:06:57.000000', NULL, 1),
(7653183, 1245708, 4008, '<td valign="top">Great image with beautiful light and good empty space. It does not have the old feel to it with lots of mid-tones and detail, as expected from woodbury type.</td>', 'Great image with beautiful light and good empty space. It does not have the old feel to it with lots of mid-tones and detail, as expected from woodbury type.', '2020-02-10 04:10:20.000000', NULL, 1),
(7653184, 1245719, 4008, '<td valign="top">Lovely scene, great soft tones. Love the wide angle approach to use the foreground steps and lines draw the eyes into the perspective. I like it. Nit picking: I would clone out the two small parts of the branch on the right , just above the trees.</td>', 'Lovely scene, great soft tones. Love the wide angle approach to use the foreground steps and lines draw the eyes into the perspective. I like it. Nit picking: I would clone out the two small parts of the branch on the right , just above the trees.', '2020-02-10 04:15:26.000000', NULL, 1),
(7653185, 1245667, 4008, '<td valign="top">They maybe never smiled, but did not look frustrated or angry either ;-) They tried to look their best. The image does not show the fine detail as expected from a woodbury type. Lots of soft focus. For me, the sepia tone and border is not enough to give it the old feel it needs.</td>', 'They maybe never smiled, but did not look frustrated or angry either ;-) They tried to look their best. The image does not show the fine detail as expected from a woodbury type. Lots of soft focus. For me, the sepia tone and border is not enough to give it the old feel it needs.', '2020-02-10 04:21:26.000000', NULL, 1),
(7653186, 1245711, 4008, '<td valign="top">Stunning, a different subject than expected, with great tones and detail. I love how the tones of background and flamingo at the bottom are equal and then the background graduates to dark while the flamingo goes light and stands out, still showing all detail in the feathers and beak.</td>', 'Stunning, a different subject than expected, with great tones and detail. I love how the tones of background and flamingo at the bottom are equal and then the background graduates to dark while the flamingo goes light and stands out, still showing all detail in the feathers and beak.', '2020-02-10 04:27:26.000000', NULL, 1),
(7653190, 1245720, 4008, '<td valign="top">It has good detail and nice soft tones, plus an old style border, but for me it does not have the feel of a Woodbury type. This is probably caused by the very light background. To me, it just looks like a normal modern image colored to achieve a bit old style effect.</td>', 'It has good detail and nice soft tones, plus an old style border, but for me it does not have the feel of a Woodbury type. This is probably caused by the very light background. To me, it just looks like a normal modern image colored to achieve a bit old style effect.', '2020-02-10 05:24:22.000000', NULL, 1),
(7653191, 1245550, 4008, '<td valign="top">Beautiful clean still life with the light and shadows really bringing out the shape of the objects and showing all the details.</td>', 'Beautiful clean still life with the light and shadows really bringing out the shape of the objects and showing all the details.', '2020-02-10 05:30:51.000000', NULL, 1),
(7653193, 1245665, 4008, '<td valign="top">This is a color image. I would not expect this for a Woodbury type. Also the image is very dark, loosing a lot of detail in the shadows. The tones and detail in the path and stone circles are fine but the rest of the image does not add to it, in my view.</td>', 'This is a color image. I would not expect this for a Woodbury type. Also the image is very dark, loosing a lot of detail in the shadows. The tones and detail in the path and stone circles are fine but the rest of the image does not add to it, in my view.', '2020-02-10 05:36:06.000000', NULL, 1),
(7653194, 1245684, 4008, '<td valign="top">Great tones and details. Unusual viewpoint, makes me dizzy in a positive way.</td>', 'Great tones and details. Unusual viewpoint, makes me dizzy in a positive way.', '2020-02-10 05:37:44.000000', NULL, 1),
(7653208, 1245706, 4008, '<td valign="top">I see a relief effect in the sky so in that sense probably a good imitation of the Woodbury process. Also lots of detail and a good distribution of tones. The scene itself I find not so appealing, rather standard.</td>', 'I see a relief effect in the sky so in that sense probably a good imitation of the Woodbury process. Also lots of detail and a good distribution of tones. The scene itself I find not so appealing, rather standard.', '2020-02-10 09:35:11.000000', NULL, 1),
(7653209, 1245241, 4008, '<td valign="top">Blur, noise and vignetting added to the background manually? I think the transition from building to background is rather big, feels unnatural. Nice tones and detail in the building and foreground.</td>', 'Blur, noise and vignetting added to the background manually? I think the transition from building to background is rather big, feels unnatural. Nice tones and detail in the building and foreground.', '2020-02-10 09:39:55.000000', NULL, 1),
(7653210, 1245497, 4008, '<td valign="top">Fantastic detail, structure and tones. If this would have been a Woodbury print it probably would have come out very nice.</td>', 'Fantastic detail, structure and tones. If this would have been a Woodbury print it probably would have come out very nice.', '2020-02-10 09:41:57.000000', NULL, 1),
(7653213, 1245653, 181505, '<td valign="top">Fantastic landscape! One of my favorites for the challenge!</td>', 'Fantastic landscape! One of my favorites for the challenge!', '2020-02-10 11:34:49.000000', NULL, 1),
(7653223, 1245718, 4008, '<td valign="top">Nice wide image with great tones and reflection, but I think a Woodbury type process would normally result in brown tones.</td>', 'Nice wide image with great tones and reflection, but I think a Woodbury type process would normally result in brown tones.', '2020-02-10 12:53:17.000000', NULL, 1),
(7653224, 1245491, 4008, '<td valign="top">Nice tones, detail and textures, but apart from that not a very interesting image to look at.</td>', 'Nice tones, detail and textures, but apart from that not a very interesting image to look at.', '2020-02-10 13:01:56.000000', NULL, 1),
(7653225, 1245670, 4008, '<td valign="top">Nice, it has an old postcard feel to it.</td>', 'Nice, it has an old postcard feel to it.', '2020-02-10 13:03:05.000000', NULL, 1),
(7653226, 1245638, 4008, '<td valign="top">If the bird is the subject of the image, why not get in closer? Zoom in or crop away those ugly metal boxes top left, this would already improve it in my view and focus the eye more on the bird.</td>', 'If the bird is the subject of the image, why not get in closer? Zoom in or crop away those ugly metal boxes top left, this would already improve it in my view and focus the eye more on the bird.', '2020-02-10 13:07:27.000000', NULL, 1),
(7653227, 1245572, 4008, '<td valign="top">Great image, love the space, the motion blur, the tones. As a Woodbury type I would probably expect more brown than grey/blue tones.</td>', 'Great image, love the space, the motion blur, the tones. As a Woodbury type I would probably expect more brown than grey/blue tones.', '2020-02-10 13:11:12.000000', NULL, 1),
(7653228, 1245671, 4008, '<td valign="top">No face of the man, no face of the horse. On purpose? Nice tones and detail.</td>', 'No face of the man, no face of the horse. On purpose? Nice tones and detail.', '2020-02-10 13:13:06.000000', NULL, 1),
(7653229, 1245630, 4008, '<td valign="top">Great close-up, lots of sharpness and detail. I am curious what color the bird actually is.</td>', 'Great close-up, lots of sharpness and detail. I am curious what color the bird actually is.', '2020-02-10 13:14:15.000000', NULL, 1),
(7653231, 1245713, 4008, '<td valign="top">Yes it has the brownish color but otherwise it does not have the atmosphere I would expect from a Woodbury type.</td>', 'Yes it has the brownish color but otherwise it does not have the atmosphere I would expect from a Woodbury type.', '2020-02-10 13:16:05.000000', NULL, 1),
(7653233, 1245712, 4008, '<td valign="top">What a beautiful bird with textures and tones from light to dark. Very appealing image.</td>', 'What a beautiful bird with textures and tones from light to dark. Very appealing image.', '2020-02-10 13:18:58.000000', NULL, 1),
(7653234, 1245658, 4008, '<td valign="top">Absolutely stunning. Beautiful lady and beautiful image. Great serene atmosphere. I love the soft mid tones and how the skin tones and the background match, while you also kept all the detail in both the black hair and the white dress. I now rated and commented the full challenge and for me this is the winner.</td>', 'Absolutely stunning. Beautiful lady and beautiful image. Great serene atmosphere. I love the soft mid tones and how the skin tones and the background match, while you also kept all the detail in both the black hair and the white dress. I now rated and commented the full challenge and for me this is the winner.', '2020-02-10 13:20:23.000000', NULL, 1),
(7653240, 1245542, 4008, '<td valign="top">I am a bit in doubt how to rate this (might come back and adjust later). It certainly has an "old" feel to it, good style of clothing and props. I think the light is rather flat, could have been more appealing with some more use of shadow for example in the face. Also the "old" feel is largely caused by the vignetting and border, which as far as I could see is not typical of the woodbury style. In the woodbury examples I think the darker edges are usually created by the distribution of light on the background.</td>', 'I am a bit in doubt how to rate this (might come back and adjust later). It certainly has an "old" feel to it, good style of clothing and props. I think the light is rather flat, could have been more appealing with some more use of shadow for example in the face. Also the "old" feel is largely caused by the vignetting and border, which as far as I could see is not typical of the woodbury style. In the woodbury examples I think the darker edges are usually created by the distribution of light on the background.', '2020-02-10 16:41:17.000000', NULL, 1),
(7653241, 1245717, 4008, '<td valign="top">Also just a few trees, but somehow this one works. Lots of small branches, lots of texture. An "old" feel to it.</td>', 'Also just a few trees, but somehow this one works. Lots of small branches, lots of texture. An "old" feel to it.', '2020-02-10 16:43:07.000000', NULL, 1),
(7653255, 1245707, 114285, '<td valign="top">Youve got the processing spot on, I feel that if you wore a period hat it would top it off.</td>', 'Youve got the processing spot on, I feel that if you wore a period hat it would top it off.', '2020-02-10 21:03:31.000000', NULL, 1),
(7653267, 1245707, 112739, '<td valign="top">I cannot not give this a 10. Unbelievably good!</td>', 'I cannot not give this a 10. Unbelievably good!', '2020-02-10 22:49:47.000000', NULL, 1),
(7653274, 1245542, 114285, '<td valign="top">I would say this is the winner, spot on editing and overall look.</td>', 'I would say this is the winner, spot on editing and overall look.', '2020-02-11 02:10:18.000000', NULL, 1),
